package com.jslw.genz.audio

/**
 * Reads the standard YouTube Music ("auto-generated by YouTube") description that downloaders store in the file:
 *
 *     Provided to YouTube by T-Series
 *
 *     Kesariya · Arijit Singh · Pritam
 *
 *     Brahmastra
 *
 *     ℗ 2022 T-Series
 *
 *     Released on: 2022-07-17
 *
 * → title, artist(s), album, year and label – without going online.
 */
object YtDescription {
    class Info(val title: String?, val artist: String?, val album: String?, val year: String?, val label: String?)

    fun parse(text: String?): Info? {
        if (text.isNullOrBlank() || !text.contains("Provided to YouTube by", ignoreCase = true)) return null
        val blocks = text.replace("\r", "").split(Regex("\n\\s*\n")).map { it.trim() }.filter { it.isNotEmpty() }
        val first = blocks.indexOfFirst { it.startsWith("Provided to YouTube by", true) }
        if (first < 0) return null
        val label = blocks[first].substringAfter("by", "").trim().takeIf { it.isNotEmpty() }
        val credit = blocks.getOrNull(first + 1)
        val parts = credit?.split(" · ")?.map { it.trim() }?.filter { it.isNotEmpty() }.orEmpty()
        val title = parts.firstOrNull()
        val artist = parts.drop(1).takeIf { it.isNotEmpty() }?.joinToString(", ")
        // the album is the next block unless it is already the ℗ / © line or a "Released on" line
        val album = blocks.getOrNull(first + 2)?.takeIf { b -> !b.startsWith("℗") && !b.startsWith("©") && !b.startsWith("Released on", true) && !b.contains('\n') }
        val year = Regex("Released on:\\s*(\\d{4})").find(text)?.groupValues?.get(1)
            ?: Regex("[℗©]\\s*(\\d{4})").find(text)?.groupValues?.get(1)
        if (title == null && album == null) return null
        return Info(title, artist, album, year, label)
    }
}
